CREATE TABLE dictionaries (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    key           TEXT NOT NULL UNIQUE,
    name_ar       TEXT,
    name_en       TEXT,
    source_type   TEXT NOT NULL DEFAULT 'ocr',  -- 'ocr' | 'hawramani' | 'arabterm'
    group_key     TEXT,
    period        TEXT,                          -- 'modern' | 'classical'
    author        TEXT,
    death_year    INTEGER,
    metadata      TEXT DEFAULT '{}'
);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE entries (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    dictionary_id   INTEGER NOT NULL REFERENCES dictionaries(id),
    headword        TEXT NOT NULL,
    headword_bare   TEXT NOT NULL,
    headword_norm   TEXT NOT NULL,
    root            TEXT,
    root_source     TEXT,                        -- 'ocr' | 'camel' | NULL
    pos             TEXT,
    form            TEXT,
    is_partial      INTEGER NOT NULL DEFAULT 0,
    definitions_text TEXT NOT NULL DEFAULT '',
    translation_en  TEXT,
    translation_fr  TEXT,
    domain          TEXT,
    external_id     TEXT,
    UNIQUE(external_id)
);
CREATE TABLE definitions (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    entry_id    INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    sense_index INTEGER NOT NULL DEFAULT 0,
    text        TEXT NOT NULL,
    is_raw      INTEGER NOT NULL DEFAULT 0,
    UNIQUE(entry_id, sense_index)
);
CREATE TABLE examples (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    entry_id    INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    idx         INTEGER NOT NULL DEFAULT 0,
    type        TEXT,
    text        TEXT NOT NULL,
    attribution TEXT,
    UNIQUE(entry_id, idx)
);
CREATE TABLE plurals (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    entry_id    INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    idx         INTEGER NOT NULL DEFAULT 0,
    text        TEXT NOT NULL,
    UNIQUE(entry_id, idx)
);
CREATE TABLE derived_forms (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    entry_id    INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    idx         INTEGER NOT NULL DEFAULT 0,
    text        TEXT NOT NULL,
    UNIQUE(entry_id, idx)
);
CREATE TABLE cross_refs (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    entry_id    INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    idx         INTEGER NOT NULL DEFAULT 0,
    text        TEXT NOT NULL,
    UNIQUE(entry_id, idx)
);
CREATE TABLE provenance (
    entry_id          INTEGER PRIMARY KEY REFERENCES entries(id) ON DELETE CASCADE,
    page_number       TEXT,
    page_file         TEXT,
    entry_index       INTEGER,
    volume            TEXT,
    hawramani_post_id INTEGER,
    hawramani_slug    TEXT,
    source_uri        TEXT
);
CREATE INDEX idx_entries_root ON entries(root);
CREATE INDEX idx_entries_root_dict ON entries(root, dictionary_id);
CREATE INDEX idx_entries_headword_bare ON entries(headword_bare);
CREATE INDEX idx_entries_headword_norm ON entries(headword_norm);
CREATE INDEX idx_entries_headword_dict ON entries(headword_bare, dictionary_id);
CREATE INDEX idx_entries_dict ON entries(dictionary_id);
CREATE INDEX idx_entries_pos ON entries(pos);
CREATE INDEX idx_defs_entry ON definitions(entry_id);
CREATE INDEX idx_examples_entry ON examples(entry_id);
CREATE INDEX idx_examples_type ON examples(type);
CREATE INDEX idx_plurals_entry ON plurals(entry_id);
CREATE INDEX idx_derived_entry ON derived_forms(entry_id);
CREATE INDEX idx_crossrefs_entry ON cross_refs(entry_id);
CREATE INDEX idx_prov_pagefile ON provenance(page_file);
CREATE VIRTUAL TABLE entries_fts USING fts5(
    headword, headword_bare, headword_norm, root,
    definitions_text,
    content=entries, content_rowid=id,
    tokenize='unicode61 remove_diacritics 2'
)
/* entries_fts(headword,headword_bare,headword_norm,root,definitions_text) */;
CREATE TABLE IF NOT EXISTS 'entries_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'entries_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'entries_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'entries_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TRIGGER entries_ai AFTER INSERT ON entries BEGIN
    INSERT INTO entries_fts(rowid, headword, headword_bare, headword_norm, root,
                            definitions_text)
    VALUES (new.id, new.headword, new.headword_bare, new.headword_norm, new.root,
            new.definitions_text);
END;
CREATE TRIGGER entries_ad AFTER DELETE ON entries BEGIN
    INSERT INTO entries_fts(entries_fts, rowid, headword, headword_bare, headword_norm,
                            root, definitions_text)
    VALUES ('delete', old.id, old.headword, old.headword_bare, old.headword_norm,
            old.root, old.definitions_text);
END;
CREATE TRIGGER entries_au AFTER UPDATE ON entries BEGIN
    INSERT INTO entries_fts(entries_fts, rowid, headword, headword_bare, headword_norm,
                            root, definitions_text)
    VALUES ('delete', old.id, old.headword, old.headword_bare, old.headword_norm,
            old.root, old.definitions_text);
    INSERT INTO entries_fts(rowid, headword, headword_bare, headword_norm, root,
                            definitions_text)
    VALUES (new.id, new.headword, new.headword_bare, new.headword_norm, new.root,
            new.definitions_text);
END;
CREATE VIRTUAL TABLE entries_translations_fts USING fts5(
    translation_en, translation_fr, domain,
    content=entries, content_rowid=id,
    tokenize='unicode61 remove_diacritics 2'
)
/* entries_translations_fts(translation_en,translation_fr,domain) */;
CREATE TABLE IF NOT EXISTS 'entries_translations_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'entries_translations_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'entries_translations_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'entries_translations_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TRIGGER entries_trans_ai AFTER INSERT ON entries BEGIN
    INSERT INTO entries_translations_fts(rowid, translation_en, translation_fr, domain)
    VALUES (new.id, new.translation_en, new.translation_fr, new.domain);
END;
CREATE TRIGGER entries_trans_ad AFTER DELETE ON entries BEGIN
    INSERT INTO entries_translations_fts(entries_translations_fts, rowid,
                                         translation_en, translation_fr, domain)
    VALUES ('delete', old.id, old.translation_en, old.translation_fr, old.domain);
END;
CREATE TRIGGER entries_trans_au AFTER UPDATE ON entries BEGIN
    INSERT INTO entries_translations_fts(entries_translations_fts, rowid,
                                         translation_en, translation_fr, domain)
    VALUES ('delete', old.id, old.translation_en, old.translation_fr, old.domain);
    INSERT INTO entries_translations_fts(rowid, translation_en, translation_fr, domain)
    VALUES (new.id, new.translation_en, new.translation_fr, new.domain);
END;
